import SubtleBadges from "./subtle/index.js";


const Badge = ({ label, icon, variant, color, isIcon, size, ...args }) => {
  if (variant === "stroke") {
    return /* @__PURE__ */ jsx(StrokeBadges, { color, icon, isIcon, label, size, ...args });
  }
  if (variant === "subtle") {
    return /* @__PURE__ */ jsx(SubtleBadges, { color, icon, isIcon, label, size, ...args });
  }
  return /* @__PURE__ */ jsx(FilledBadges, { color, icon, isIcon, label, size, ...args });
};
Badge.displayName = "Badge";
